UPDATE risk_rules SET
    llm_prompt = 'Найди размер и способы внесения обеспечения заявки на участие в закупке (ст. 44 44-ФЗ, ст. 3.2 223-ФЗ). По 44-ФЗ обеспечение заявки не должно превышать 1% НМЦК при цене до 20 млн руб. и до 5% при большей цене. ВАЖНО: проверяй ТОЛЬКО условия подачи заявки на участие. НЕ ПУТАТЬ с обеспечением исполнения контракта (ст. 96 44-ФЗ) — размер обеспечения контракта до 30% является полностью законным и НЕ является нарушением по этому правилу. Если фрагмент относится к обеспечению исполнения контракта или гарантии на исполнение, вердикт: NOT_FOUND или OK.',
    semantic_query = 'обеспечение заявки на участие в аукционе конкурсе размер обеспечения заявки процент начальной максимальной цены превышение способ внесения'
WHERE id = 'bid_security_excessive';

UPDATE risk_rules SET
    llm_prompt = 'Проверь размер пени и штрафов поставщика по ч. 5–8 ст. 34 44-ФЗ и ПП РФ № 1042. Риском RED является произвольный штраф (например, 5% или 10% от всей цены контракта за любое нарушение вместо дифференцированной шкалы по ПП 1042) или превышение законного размера пени (1/300 ставки ЦБ РФ). ВАЖНО: условия о раскрытии независимой гарантии или безакцептном списании проверяются отдельным правилом и не относятся к данному правилу. Рекомендация: протокол разногласий с требованием привести размеры штрафов в соответствие с ПП РФ № 1042.'
WHERE id = 'unreasonable_penalty';

UPDATE risk_rules SET
    is_active = false
WHERE id = 'trademark_no_equivalent';
